local DaggerMaker = {}
local PRODUCTS = {
    iron_dagger = { name = "Železen bodalec", ironCost = 1, time = 1, cost = 12, attack = 4, durability = 15, description = "Preprost železen bodalec." },
    steel_dagger = { name = "Jeklen bodalec", steelCost = 1, time = 2, cost = 35, attack = 7, durability = 22, prestige = 1, description = "Jeklen bodalec za viteze." },
    silver_hilt_dagger = { name = "Srebrnorčajni bodalec", steelCost = 1, silverCost = 1, time = 4, cost = 90, attack = 10, durability = 28, prestige = 3, happiness = 1, description = "Bodalec s srebrnim ročajem." },
    stiletto = { name = "Stilet", steelCost = 1, silverCost = 1, time = 5, cost = 200, attack = 13, durability = 25, prestige = 5, happiness = 1, description = "Stilet za prebadanje oklepov." },
    jewel_pommel_dagger = { name = "Draguljni bodalec", steelCost = 2, goldCost = 1, jewelCost = 1, time = 8, cost = 600, attack = 18, durability = 40, prestige = 12, happiness = 3, description = "Bodalec z zlatim okovjem in draguljem." },
    royal_ceremonial_dagger = { name = "Kraljevski slovesni bodalec", steelCost = 2, goldCost = 2, silverCost = 1, jewelCost = 2, pearlCost = 1, time = 12, cost = 1600, attack = 28, durability = 60, prestige = 42, happiness = 9, description = "Veliki kraljevski slovesni bodalec z dragulji in biseri." },
}
local BUILDINGS = {
    workshop = { name = "Bodalaška delavnica", cost = { gold = 260, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Bodalaška kovačija", cost = { gold = 800, wood = 200, stone = 200, iron = 6 }, upkeep = 20, qualityBonus = 18 },
    tempering_room = { name = "Žarilnica", cost = { gold = 1800, wood = 280, stone = 400, silver = 25, steel = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_dagger_atelier = { name = "Kraljevski atelje bodalcev", cost = { gold = 7000, wood = 500, stone = 700, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 30 },
}
DaggerMaker.ironStock = 12; DaggerMaker.steelStock = 12; DaggerMaker.silverStock = 8; DaggerMaker.goldStock = 6; DaggerMaker.jewelStock = 6; DaggerMaker.pearlStock = 4
DaggerMaker.productStock = {}; DaggerMaker.buildings = {}; DaggerMaker.maker = nil; DaggerMaker.activeMaking = {}; DaggerMaker.totalProducts = 0; DaggerMaker.dayTimer = 0
function DaggerMaker.init() DaggerMaker.ironStock=12; DaggerMaker.steelStock=12; DaggerMaker.silverStock=8; DaggerMaker.goldStock=6; DaggerMaker.jewelStock=6; DaggerMaker.pearlStock=4; DaggerMaker.productStock={}; DaggerMaker.buildings={}; DaggerMaker.maker=nil; DaggerMaker.activeMaking={}; DaggerMaker.totalProducts=0; DaggerMaker.dayTimer=0; print("[DaggerMaker] Royal Dagger Maker System initialized (6 products, 4 buildings)") end
function DaggerMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DaggerMaker.maker={name=n or ("Bodalar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bodalar najet: %s (spretnost: %d)",DaggerMaker.maker.name,s),"success") end; return true end
function DaggerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DaggerMaker.build(id) local ok,e=DaggerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DaggerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DaggerMaker.getQualityBonus() local b=0; for _,bd in ipairs(DaggerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DaggerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and DaggerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and DaggerMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and DaggerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DaggerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DaggerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DaggerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DaggerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not DaggerMaker.maker then return false,"Potreben bodalar" end; return true end
function DaggerMaker.make(pt,qty) qty=qty or 1; local ok,e=DaggerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then DaggerMaker.ironStock=DaggerMaker.ironStock-d.ironCost*qty end; if d.steelCost then DaggerMaker.steelStock=DaggerMaker.steelStock-d.steelCost*qty end; if d.silverCost then DaggerMaker.silverStock=DaggerMaker.silverStock-d.silverCost*qty end; if d.goldCost then DaggerMaker.goldStock=DaggerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DaggerMaker.jewelStock=DaggerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DaggerMaker.pearlStock=DaggerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DaggerMaker.maker then t=math.max(1,t-math.floor(DaggerMaker.maker.skill/12)) end; table.insert(DaggerMaker.activeMaking,{id="dagger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DaggerMaker.completeMaking(m) local q=1.0+(DaggerMaker.getQualityBonus()/100); if DaggerMaker.maker then q=q+(DaggerMaker.maker.skill/180) end; q=math.min(2.0,q); DaggerMaker.productStock[m.productType]=(DaggerMaker.productStock[m.productType] or 0)+m.quantity; DaggerMaker.totalProducts=DaggerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DaggerMaker.maker then DaggerMaker.maker.itemsMade=DaggerMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then DaggerMaker.maker.skill=math.min(100,DaggerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bodalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"dagger.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function DaggerMaker.update(dt) if not _G.state then return end; DaggerMaker.dayTimer=DaggerMaker.dayTimer+dt; if DaggerMaker.dayTimer>=30 then DaggerMaker.dayTimer=0; for i=#DaggerMaker.activeMaking,1,-1 do local m=DaggerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DaggerMaker.completeMaking(m); table.remove(DaggerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DaggerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DaggerMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DaggerMaker.getStats() return {ironStock=DaggerMaker.ironStock,steelStock=DaggerMaker.steelStock,silverStock=DaggerMaker.silverStock,goldStock=DaggerMaker.goldStock,jewelStock=DaggerMaker.jewelStock,pearlStock=DaggerMaker.pearlStock,productStock=DaggerMaker.productStock,numBuildings=#DaggerMaker.buildings,hasMaker=DaggerMaker.maker~=nil,makerName=DaggerMaker.maker and DaggerMaker.maker.name or "—",makerSkill=DaggerMaker.maker and DaggerMaker.maker.skill or 0,activeMaking=#DaggerMaker.activeMaking,totalProducts=DaggerMaker.totalProducts} end
return DaggerMaker
